// Splits one CSV line into its fields.
export function parseLine(line) {
  const fields = [];
  let field = '';
  let quoted = false;
  let wasQuoted = false;
  const end = () => {
    fields.push(wasQuoted ? field : field.trim());
    field = '';
    wasQuoted = false;
  };
  for (let i = 0; i < line.length; i += 1) {
    const ch = line[i];
    if (quoted) {
      if (ch === '"' && line[i + 1] === '"') {
        field += '"';
        i += 1;
      } else if (ch === '"') quoted = false;
      else field += ch;
    } else if (ch === '"') {
      quoted = true;
      wasQuoted = true;
      field = '';
    } else if (ch === ',') end();
    else if (!wasQuoted) field += ch;
  }
  end();
  return fields;
}
